proposal.patch_content:
{
  "global_tool_guard": {
    "min_input_length": 1,
    "reject_empty_strings": true,
    "on_violation": "skip_call_and_log_warning"
  }
}

{
  "memory_validation_rules": {
    "unique_keys_per_user": ["account_tier"],
    "on_write_conflict": "reject_and_require_explicit_overwrite",
    "on_read_conflict": "resolve_by_most_recent_timestamp_and_flag",
    "conflict_flag_field": "memory_conflict",
    "conflict_flag_value": {"key": "account_tier", "candidates": ["Gold", "Silver"], "resolved": "<most_recent>", "requires_user_confirmation": true},
    "stale_entry_ttl_days": 90,
    "dedupe_scope": "user_id"
  }
}
